# Road signs, markings and signals of Denmark, from Bekendtgørelse om vejafmærkning (BEK 425 af 13/04/2023; first
# written from BEK 1632 af 20/12/2017) and Færdselsloven (LBK 118 af 12/01/2026).
# Each item: code, Danish name, Persian title, Persian text, and `look` (the official design, for the picture prompt).

S = []

def cat(id, title, intro, shape, items):
    S.append({'id': id, 'title': title, 'intro': intro, 'shape': shape, 'items': items})

def it(code, da, fa, text, look, key=None):
    k = key or 's-' + code.lower().replace(' ', '').replace(',', '-')
    return {'key': k, 'code': code, 'da': da, 'fa': fa, 'text': text, 'look': look}

